"""Object storage abstraction. Keys are generated by the application, never from user filenames."""

from __future__ import annotations

import re
from collections.abc import Iterator
from dataclasses import dataclass
from datetime import datetime
from typing import BinaryIO, Protocol

_SEGMENT = re.compile(r"^[A-Za-z0-9_][A-Za-z0-9._-]{0,127}$")
MAX_KEY_LENGTH = 512


class StorageError(Exception):
    """Base class for storage failures."""


class InvalidKeyError(StorageError):
    """The object key is not a safe, application-generated key."""


class ObjectNotFoundError(StorageError):
    """No object exists for the key."""


class ObjectTooLargeError(StorageError):
    """The stream exceeded the allowed size."""


@dataclass(frozen=True, slots=True)
class StoredObject:
    key: str
    size: int
    sha256: str


@dataclass(frozen=True, slots=True)
class ObjectInfo:
    key: str
    size: int
    modified_at: datetime  # timezone-aware (UTC)


def validate_key(key: str) -> str:
    """Allow '/'-separated segments of [A-Za-z0-9._-], no '..' or dotfiles."""
    if not key or len(key) > MAX_KEY_LENGTH:
        raise InvalidKeyError("key is empty or too long")
    segments = key.split("/")
    for segment in segments:
        if segment in {".", ".."} or not _SEGMENT.fullmatch(segment):
            raise InvalidKeyError("key contains an unsafe segment")
    return key


class ObjectStorage(Protocol):
    """Synchronous storage interface (called from Celery directly and from the API via a thread)."""

    def put(self, key: str, stream: BinaryIO, *, max_bytes: int | None = None) -> StoredObject:
        """Atomically store the stream; return size and SHA-256 computed while streaming."""
        ...

    def open(self, key: str) -> BinaryIO:
        """Open for binary reading. Raises ObjectNotFoundError."""
        ...

    def exists(self, key: str) -> bool: ...

    def delete(self, key: str) -> bool:
        """Delete the object. Returns False if it did not exist (idempotent)."""
        ...

    def iter_objects(self, prefix: str = "") -> Iterator[ObjectInfo]:
        """Every stored object (optionally under a prefix) with size and modification time."""
        ...

    def sweep_temporary(self, older_than_s: float) -> int:
        """Remove leftovers of interrupted writes (stale temp files / unfinished multipart
        uploads) older than the given age. Returns how many were removed."""
        ...

    def delete_prefix(self, prefix: str) -> int:
        """Delete every object under a '/'-terminated-free prefix; returns the count."""
        ...
